            progress / current_template->secondary_samples[sample_index].delta_length
                * (current_template->primary_samples[sample_index + 1].special_scalar
                   - current_template->primary_samples[sample_index].special_scalar)
            + current_template->primary_samples[sample_index].special_scalar;
